    static void NestedGrowth(TargetPlatform p){bool big=p!=TargetPlatform.Win32;foreach(Growth g in GrowthRoutes)foreach(int count in new int[]{0,1,2,3,15,16,17,27,28,29,64,257,1024}){Branch branch=Array.Find(Branches,candidateBranch=>candidateBranch.Name==g.Branch);XmlDocument d=Component(branch);XmlElement node=ComponentNode(d);if(g.ParentPath.Length!=0)foreach(string name in g.ParentPath.Split('/'))node=Add(node,name);for(int i=0;i<count;++i)Add(node,g.Name);AssetBuffer b=TestDoc("nested list growth/"+g.Branch+"/"+g.ParentPath+"/"+g.Name,d,p);int owner=32;if(g.ParentSteps.Length!=0)foreach(string step in g.ParentSteps.Split('/')){int offset=Int32.Parse(step.Substring(1),CultureInfo.InvariantCulture);owner=step[0]=='I'?owner+offset:(int)Word(b.InstanceData,owner+offset+(step[0]=='L'?4:0),big);}Check(Word(b.InstanceData,owner+g.Offset,big)==count,"nested growth count");uint target=Word(b.InstanceData,owner+g.Offset+4,big);Check(count==0?target==0:target>=32&&target+g.Size*count<=b.InstanceData.Length,"nested list independent stride/extent");}}
    static void SpecialFlags(TargetPlatform p){bool big=p!=TargetPlatform.Win32;foreach(Route route in JoinRoutes())foreach(Field f in route.Fields)if(f.Kind.Contains("flags")){
        string map=f.Kind=="objectfilter-relationship-flags"?"ObjectFilterRelationship":f.Kind=="objectstatus-nullable-flags"?"ObjectStatusType":"KindOfType";int bitCount=map=="ObjectFilterRelationship"?4:map=="ObjectStatusType"?224:284;int wordCount=(bitCount+31)/32;
        foreach(EnumCase e in EnumMaps[map]){if(e.Value>=bitCount||e.Name=="ALL")continue;foreach(string token in new string[]{e.Name,"+"+e.Name,"-"+e.Name}){XmlElement node;XmlDocument d=RouteDoc(route,out node);SetField(node,f,token);AssetBuffer b=TestDoc("full bitset enum/"+route.Path+"/"+f.Name+"/"+token,d,p);int at=RouteAt(route,b,big)+f.Offset;if(f.Kind=="objectstatus-nullable-flags")at=(int)Word(b.InstanceData,at,big);for(int j=0;j<wordCount;++j)Check(Word(b.InstanceData,at+4*j,big)==(j==e.Value/32?1u<<(int)(e.Value%32):0),"every bit index independent word ABI");}}
        foreach(string token in new string[]{"ALL","ALL -INFANTRY","all UNKNOWN"}){XmlElement node;XmlDocument d=RouteDoc(route,out node);SetField(node,f,token);AssetBuffer b=TestDoc("ALL full words including padding",d,p);int at=RouteAt(route,b,big)+f.Offset;if(f.Kind=="objectstatus-nullable-flags")at=(int)Word(b.InstanceData,at,big);for(int j=0;j<wordCount;++j)Check(Word(b.InstanceData,at+4*j,big)==UInt32.MaxValue,"ALL original nonadvancing branch");}
    }}
